import React, { useState } from 'react';

// A simple hash function to get a consistent "random" position for a city
const cityToPosition = (city) => {
  let hash = 0;
  for (let i = 0; i < city.length; i++) {
    hash = city.charCodeAt(i) + ((hash << 5) - hash);
  }
  const x = (hash & 0xFF) % 90 + 5; // 5% to 95%
  const y = ((hash >> 8) & 0xFF) % 80 + 10; // 10% to 90%
  return { x, y };
};

const MapView = ({ properties }) => {
  const [activeProperty, setActiveProperty] = useState(null);
  const [filter, setFilter] = useState('all');

  const filteredProperties = properties.filter(p => {
    if (filter === 'all') return true;
    return p.status === filter;
  });

  return (
    <div className="map-container shadow-lg">
      <div className="map-background">
        {/* This is a decorative background image */}
      </div>

      <div style={{ position: 'absolute', top: 20, right: 20, zIndex: 100 }}>
        <div className="btn-group shadow-sm bg-white rounded" role="group">
          <button type="button" className={`btn btn-sm ${filter === 'all' ? 'btn-dark' : 'btn-outline-dark'}`} onClick={() => setFilter('all')}>الكل</button>
          <button type="button" className={`btn btn-sm ${filter === 'للبيع' ? 'btn-danger' : 'btn-outline-danger'}`} onClick={() => setFilter('للبيع')}>للبيع</button>
          <button type="button" className={`btn btn-sm ${filter === 'للإيجار' ? 'btn-primary' : 'btn-outline-primary'}`} onClick={() => setFilter('للإيجار')}>للإيجار</button>
        </div>
      </div>

      <div className="map-content">
        {filteredProperties.map(prop => {
          const position = prop.coordinates || cityToPosition(prop.location?.city || 'Unknown');
          return (
            <div
              key={prop.id}
              className={`map-marker ${prop.status === 'للبيع' ? 'marker-sale' : 'marker-rent'}`}
              style={{ left: `${position.x}%`, top: `${position.y}%` }}
              onClick={() => setActiveProperty(prop)}
              title={`${prop.type} in ${prop.location?.city}`}
            >
              <div className="pin-body"><span className="pin-icon">🏠</span></div>
              <div className="pin-pulse"></div>
            </div>
          );
        })}

        {activeProperty && (
          <div
            className="map-popup fade-in"
            style={{
              left: `${(activeProperty.coordinates || cityToPosition(activeProperty.location?.city || 'Unknown')).x}%`,
              top: `${(activeProperty.coordinates || cityToPosition(activeProperty.location?.city || 'Unknown')).y}%`
            }}
          >
            <button className="btn-close btn-sm" onClick={() => setActiveProperty(null)}></button>
            <img src={activeProperty.imageUrl} alt={activeProperty.type} />
            <div className="map-popup-body">
              <strong>{activeProperty.type}</strong>
              <div className="text-muted small">{activeProperty.location?.city}</div>
              <div className="text-success fw-bold">{activeProperty.price?.toLocaleString()} ج</div>
            </div>
          </div>
        )}
      </div>
       <div className="map-legend">
        <h5 className="mb-3">خريطة العقارات</h5>
        <p className="small text-muted">
          هذه خريطة توضيحية لعرض مواقع العقارات بشكل تقريبي. اضغط على أي علامة 🏠 لعرض تفاصيل العقار.
        </p>
      </div>
    </div>
  );
};

export default MapView;
